{rad(acos(1/x))};
\addplot [
    domain=1:2,
    samples=100,
    color=blue,
    thick
]
{rad(acos(1/x))};
\node[anchor=south west] at (axis cs:2,3.5) {$\sec^{-1}(x)$};
\end{axis}
\end{tikzpicture}
\end{document}
```

